import gurobipy
from gurobipy import GRB

def solve_problem():
    tables = CSVQA_DATA.get('tables', [])
    table = None
    for t in tables:
        if t.get('table_id') == 'file_0_view_0':
            table = t
            break
    if table is None:
        raise ValueError('Table file_0_view_0 not found in CSVQA_DATA')
    records = table.get('records', [])
    products = []
    L_i = {}
    M_i = {}
    P_i = {}
    C_i = {}
    for rec in records:
        values = rec.get('values', {})
        prod = values.get('Product Name')
        if prod is None:
            continue
        products.append(prod)
        try:
            L_i[prod] = float(values.get('Labor per unit', 0))
            M_i[prod] = float(values.get('Material per unit', 0))
            P_i[prod] = float(values.get('Selling Price', 0))
            C_i[prod] = float(values.get('Variable Cost', 0))
        except Exception as e:
            raise ValueError(f'Error parsing numeric values for product {prod}: {e}')
    for prod in products:
        if prod not in L_i or prod not in M_i or prod not in P_i or (prod not in C_i):
            raise ValueError(f'Missing parameter for product {prod}')
    model = gurobipy.Model()
    model.setParam('MIPGap', 1e-06)
    x = model.addVars(products, lb=0, vtype=GRB.CONTINUOUS, name='')
    profit_expr = gurobipy.quicksum(((P_i[p] - C_i[p]) * x[p] for p in products))
    model.setObjective(profit_expr - 4500, GRB.MAXIMIZE)
    labor_expr = gurobipy.quicksum((L_i[p] * x[p] for p in products))
    model.addConstr(labor_expr <= 1650, name='labor')
    material_expr = gurobipy.quicksum((M_i[p] * x[p] for p in products))
    model.addConstr(material_expr <= 1850, name='material')
    model.optimize()
    if model.Status == GRB.OPTIMAL:
        print(f'ObjVal: {model.ObjVal}')
        for var in model.getVars():
            print(f'{var.VarName}: {var.X}')
    else:
        print(f'Solver status: {model.Status}')
    return model
m = solve_problem()
